queries.sparql:
PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?party ?partyLabel ?affiliation ?affiliationLabel WHERE {
  GRAPH <https://data.oireachtas.ie/graph/houses> { ?selectedTerm a agents:DailTerm . }
  VALUES ?selectedTerm { <https://data.oireachtas.ie/ie/oireachtas/house/dail/34> }
  GRAPH <https://data.oireachtas.ie/graph/parties> {
    ?party a members:ParliamentaryParty ; members:activeDuringTerm ?selectedTerm .
    OPTIONAL { ?party skos:prefLabel ?partyLabel . FILTER(LANG(?partyLabel) = "en") }
  }
  OPTIONAL { GRAPH <https://data.oireachtas.ie/graph/political-affiliations/identities> {
    ?party members:hasPoliticalAffiliationIdentity ?affiliation .
    ?affiliation a members:PoliticalAffiliationIdentity .
    OPTIONAL { ?affiliation skos:prefLabel ?affiliationLabel . FILTER(LANG(?affiliationLabel) = "en") }
  } }
} ORDER BY ?affiliationLabel ?partyLabel ?party ?affiliation LIMIT 100

PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?party ?label WHERE {
  GRAPH <https://data.oireachtas.ie/graph/houses> { <https://data.oireachtas.ie/ie/oireachtas/house/dail/34> a agents:DailTerm . }
  GRAPH <https://data.oireachtas.ie/graph/parties> {
    ?party a members:ParliamentaryParty ; members:activeDuringTerm <https://data.oireachtas.ie/ie/oireachtas/house/dail/34> .
    OPTIONAL { ?party skos:prefLabel ?label . }
  }
} ORDER BY ?party ?label LIMIT 100

PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?member ?memberName ?membership ?membershipRange ?membershipStart ?membershipEnd ?episode ?party ?partyLabel ?partyRange ?partyStart ?partyEnd ?affiliation ?affiliationLabel ?term WHERE {
GRAPH ?memberGraph { ?member a agents:Member . ?membership a members:DailMembership . ?episode a members:PartyMembership . ?member members:hasMembersMembership ?membership . ?membership members:inHouseTerm ?term . ?member members:hasMembersMembership ?episode . ?episode members:inOireachtasMembership ?membership . ?episode members:isPartyMembershipOf ?party . OPTIONAL { ?member foaf:name ?memberName . } OPTIONAL { ?membership members:hasMembershipDateRange ?membershipRange .
      ?membershipRange a members:DateRange .
      OPTIONAL { ?membershipRange members:StartDate ?membershipStart . }
      OPTIONAL { ?membershipRange members:EndDate ?membershipEnd . } } OPTIONAL { ?episode members:hasMembershipDateRange ?partyRange .
      ?partyRange a members:DateRange .
      OPTIONAL { ?partyRange members:StartDate ?partyStart . }
      OPTIONAL { ?partyRange members:EndDate ?partyEnd . } } } FILTER(STRSTARTS(STR(?memberGraph), "https://data.oireachtas.ie/graph/member/"))
GRAPH <https://data.oireachtas.ie/graph/houses> { ?term a agents:DailTerm . VALUES ?term { <https://data.oireachtas.ie/ie/oireachtas/house/dail/34> } }
GRAPH <https://data.oireachtas.ie/graph/parties> { ?party a members:ParliamentaryParty . VALUES ?party { <https://data.oireachtas.ie/ie/oireachtas/party/dail/34/Labour_Party> } ?party members:activeDuringTerm ?term . OPTIONAL { ?party skos:prefLabel ?partyLabel . FILTER(LANG(?partyLabel) = "en") } }
OPTIONAL { GRAPH <https://data.oireachtas.ie/graph/political-affiliations/identities> { ?affiliation a members:PoliticalAffiliationIdentity . ?party members:hasPoliticalAffiliationIdentity ?affiliation . OPTIONAL { ?affiliation skos:prefLabel ?affiliationLabel . FILTER(LANG(?affiliationLabel) = "en") } } }
} ORDER BY ?affiliationLabel ?memberName ?partyStart ?membershipStart ?episode ?membership LIMIT 100
